<div class="grid-stats" style="margin-bottom:20px"><div class="stat-card"><div class="stat-icon"><i class="fas fa-list" aria-hidden="true"></i></div><div class="stat-num"><?= e((int) ($totalGeral ?? 0)) ?></div><div class="stat-label">Registos desta igreja</div></div><div class="stat-card"><div class="stat-icon"><i class="fas fa-filter" aria-hidden="true"></i></div><div class="stat-num"><?= e((int) ($quantidade ?? 0)) ?></div><div class="stat-label">Registos apresentados (máx. 500)</div></div><div class="stat-card"><div class="stat-icon"><i class="fas fa-clock" aria-hidden="true"></i></div><div class="stat-num" style="font-size:16px"><?= !empty($ultimoLogin['criado_em']) ? e(date('d/m/Y H:i', strtotime((string) $ultimoLogin['criado_em']))) : '—' ?></div><div class="stat-label">Último login desta igreja</div></div></div>
